const parse = c => { const m = c.match(/[\d.]+/g).map(Number); return m; };
const lum = ([r,g,b]) => { const f = v => { v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4);}; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const bgOf = el => { while(el){ const c = getComputedStyle(el).backgroundColor; const p = parse(c); if(p.length<4 || p[3]>0) return p.slice(0,3); el = el.parentElement || (el.getRootNode()&&el.getRootNode().host);} return [255,255,255]; };
const cr = el => { const s = getComputedStyle(el); const f = parse(s.color).slice(0,3); const b = bgOf(el); const L1=lum(f),L2=lum(b); return {txt: el.textContent.trim().slice(0,30), color:s.color, bg:'rgb('+b.join(',')+')', ratio: ((Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05)).toFixed(2), fs:s.fontSize, fw:s.fontWeight}; };
